@Post('article/xiaohongshu/cache-export')
@HttpCode(200)
async exportXhsCachedSelection(
  @Body() body: unknown,
  @Request() req: Req,
  @Response() res: Res,
) {
  if (!this.authorized(req, res, true)) return;
  if (
    privateOnlineMode() ||
    process.env.WEWE_ACCEPTANCE_MODE === '1' ||
    !this.xiaohongshu ||
    !this.prisma
  )
    return res.status(409).json({ message: '当前模式不能保存本地缓存。' });
  if (this.running || this.pickerRunning)
    return res.status(409).json({ message: '请等待当前本地操作完成。' });
  const controller = new AbortController();
  const abort = () => controller.abort();
  const close = () => {
    if (!res.writableEnded) controller.abort();
  };
  req.once('aborted', abort);
  res.once('close', close);
  if (req.aborted || res.destroyed) controller.abort();
  this.running = true;
  try {
    const items = (body as { items?: unknown })?.items;
    const confirmedToken = (body as { pickToken?: unknown })?.pickToken;
    if (
      !body ||
      Array.isArray(body) ||
      (confirmedToken !== undefined && confirmedToken !== this.xhsConfirmedGrant) ||
      Object.keys(body).some((key) => !['items', 'pickToken'].includes(key)) ||
      ((body as { pickToken?: unknown }).pickToken !== undefined && typeof (body as { pickToken?: unknown }).pickToken !== 'string') ||
      !Array.isArray(items) ||
      !items.length ||
      items.length > XHS_CACHED_SCOPE_LIMIT ||
      items.some(
        (item) =>
          !item ||
          typeof item !== 'object' ||
          Array.isArray(item) ||
          Object.keys(item).some(
            (key) => !['id', 'creatorId'].includes(key),
          ) ||
          typeof item.id !== 'string' ||
          !item.id ||
          item.id.length > 300 ||
          typeof item.creatorId !== 'string' ||
          !item.creatorId ||
          item.creatorId.length > 128,
      )
    )
      throw new ArticleDownloadError('所选归档范围无效。', 400, {
        code: 'XHS_CACHED_SCOPE_INVALID',
      });
    // Freeze membership and trusted metadata before the single native selection.
    // This request grants only these IDs at its selected XHS target; no reusable token.
    const frozen = await freezeCachedXhsSelection(
      this.prisma,
      items as XhsCachedTarget[],
    );
    if (controller.signal.aborted) return;
    const store = this.localStore('xiaohongshu');
    const settings = await store.read();
    let directory = settings.directory;
    if (settings.askEveryTime) {
      const token = (body as { pickToken?: string }).pickToken;
      if (token) {
        if (token !== this.xhsPickerGrant)
          throw new ArticleDownloadError('请先确认本次保存目录。', 409, { code: 'DIRECTORY_PICK_REQUIRED' });
      } else {
        // Older clients retain the original explicit native-picker flow.
        this.xhsPickerGrant = undefined;
        this.xhsConfirmedGrant = undefined;
        this.pickerRunning = true;
        const selected = await pickArticleDirectory(directory, { platform: 'xiaohongshu', count: frozen.length, signal: controller.signal });
        if (controller.signal.aborted) return;
        if (selected === null) return res.json({ results: [], cancelled: true });
        directory = (await store.rememberPickedDirectory(selected)).directory;
        this.pickerRunning = false;
      }
    }
    this.xhsPickerGrant = undefined;
    this.xhsConfirmedGrant = undefined;
    if (controller.signal.aborted) return;
    const receipt = await saveFrozenXhsCache(
      frozen,
      store,
      directory,
      (creator, id) => this.xiaohongshu!.prepareLocalDownload(creator, id),
      () => controller.signal.aborted,
    );
    if (!controller.signal.aborted) {
      res.setHeader('Cache-Control', 'private, no-store');
      return res.json(receipt);
    }
  } catch (error) {
    if (!controller.signal.aborted) return this.failure(error, res);
  } finally {
    req.removeListener('aborted', abort);
    res.removeListener('close', close);
    this.pickerRunning = false;
    this.running = false;
  }
}

